404	func runTrailUpdate(ctx context.Context, w, errW io.Writer, insecureHTTP bool, statusStr, title, body, branch string, labelAdd, labelRemove []string) error {
405		_ = errW // reserved for future warnings
406	
407		client, err := NewAuthenticatedAPIClient(insecureHTTP)
408		if err != nil {
409			return fmt.Errorf("authentication required: %w", err)
410		}
411	
412		host, owner, repoName, err := gitremote.ResolveRemoteRepo(ctx, "origin")
413		if err != nil {
414			return fmt.Errorf("failed to resolve repository: %w", err)
415		}
416	
417		// Determine branch
418		if branch == "" {
419			branch, err = GetCurrentBranch(ctx)
420			if err != nil {
421				return fmt.Errorf("failed to determine current branch: %w", err)
422			}
423		}
424	
425		// Find the trail by branch
426		found, err := findTrailByBranch(ctx, client, host, owner, repoName, branch)
427		if err != nil {
428			return err
429		}
430		if found == nil {
431			return fmt.Errorf("no trail found for branch %q", branch)
432		}
433	
434		// Interactive mode when no flags are provided
435		noFlags := statusStr == "" && title == "" && body == "" && labelAdd == nil && labelRemove == nil
436		if noFlags {
437			metadata := found.ToMetadata()
438			// Build status options with current value as default.
439			var statusOptions []huh.Option[string]
440			for _, s := range trail.ValidStatuses() {
441				if (s == trail.StatusMerged || s == trail.StatusClosed) && s != metadata.Status {
442					continue
443				}
444				label := string(s)
445				if s == metadata.Status {
446					label += " (current)"
447				}
448				statusOptions = append(statusOptions, huh.NewOption(label, string(s)))
449			}
450			statusStr = string(metadata.Status)
451			title = metadata.Title
452			body = metadata.Body
453	
454			form := NewAccessibleForm(
455				huh.NewGroup(
456					huh.NewSelect[string]().
457						Title("Status").
458						Options(statusOptions...).
459						Value(&statusStr),
460					huh.NewInput().
461						Title("Title").
462						Value(&title),
463					huh.NewText().
464						Title("Body").
465						Value(&body),
466				),
467			)
468			if formErr := form.Run(); formErr != nil {
469				return handleFormCancellation(w, "Trail update", formErr)
470			}
471		}
472	
473		// Validate status if provided
474		if statusStr != "" {
475			status := trail.Status(statusStr)
476			if !status.IsValid() {
477				return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
478			}
479		}
480	
481		// Build update request with only changed fields
482		updateReq := buildTrailUpdateRequest(found, statusStr, title, body, labelAdd, labelRemove)
483	
484		resp, err := client.Patch(ctx, trailsBasePath(host, owner, repoName)+"/"+found.TrailID, updateReq)
485		if err != nil {
486			return fmt.Errorf("failed to update trail: %w", err)
487		}
488		defer resp.Body.Close()
489		if err := checkTrailResponse(resp); err != nil {
490			return err
491		}
492	
493		var updateResp api.TrailUpdateResponse
494		if err := api.DecodeJSON(resp, &updateResp); err != nil {
495			return fmt.Errorf("failed to decode update response: %w", err)
496		}
497	
498		fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
499		return nil
500	}
