558	// runTrailCreateInteractive runs the interactive form for trail creation.
559	// Prompts for title, body, branch (derived from title), and status.
560	func runTrailCreateInteractive(title, body, branch, statusStr *string) error {
561		// Step 1: Title and body
562		form := NewAccessibleForm(
563			huh.NewGroup(
564				huh.NewInput().
565					Title("Trail title").
566					Placeholder("What are you working on?").
567					Value(title),
568				huh.NewText().
569					Title("Body (optional)").
570					Value(body),
571			),
572		)
573		if err := form.Run(); err != nil {
574			return fmt.Errorf("form cancelled: %w", err)
575		}
576		*title = strings.TrimSpace(*title)
577		if *title == "" {
578			return errors.New("trail title is required")
579		}
580	
581		// Step 2: Branch (derived from title) and status
582		suggested := slugifyTitle(*title)
583		*branch = suggested
584	
585		// Build status options, excluding done/closed
586		var statusOptions []huh.Option[string]
587		for _, s := range trail.ValidStatuses() {
588			if s == trail.StatusMerged || s == trail.StatusClosed {
589				continue
590			}
591			statusOptions = append(statusOptions, huh.NewOption(string(s), string(s)))
592		}
593		if *statusStr == "" {
594			*statusStr = string(trail.StatusDraft)
595		}
596	
597		form = NewAccessibleForm(
598			huh.NewGroup(
599				huh.NewInput().
600					Title("Branch name").
601					Placeholder(suggested).
602					Value(branch),
603				huh.NewSelect[string]().
604					Title("Status").
605					Options(statusOptions...).
606					Value(statusStr),
607			),
608		)
609		if err := form.Run(); err != nil {
610			return fmt.Errorf("form cancelled: %w", err)
611		}
612		*branch = strings.TrimSpace(*branch)
613		if *branch == "" {
614			*branch = suggested
615		}
616		return nil
617	}
